class Box:
    def __init__(self, v):
        self.v = v
    def __eq__(self, other):
        return isinstance(other, Box) and self.v == other.v
    def __hash__(self):
        return hash(self.v)          # depends on mutable state

b = Box(1)
s = {b}
print("before mutation:", b in s, "len:", len(s))
b.v = 2                               # hash changes, bucket does not
print("after b.v = 2  :", b in s, "len:", len(s))
print("Box(1) in s    :", Box(1) in s, "(right bucket, but __eq__ fails)")
print("still iterable :", [x.v for x in s])

class OnlyEq:
    def __eq__(self, other):
        return True
print("__hash__ with only __eq__:", OnlyEq.__hash__)

print("1, 1.0, True collapse:", {1, 1.0, True})
print("hash(-1), hash(-2):", hash(-1), hash(-2))
